import{j as e}from"./vendor-motion-D-QS5Tde.js";import{H as r}from"./index-DTryBJkQ.js";import{N as o,F as l}from"./Footer-KawF-dDP.js";import{P as d,C as t,N as c}from"./NextProject-BUYY37sz.js";import{P as h}from"./ProjectOverview-DL46-v3B.js";import{C as s}from"./CsSection-D4zIf1tb.js";import{C as a}from"./CsFeatureGrid-BbPEq4n9.js";import{C as i}from"./CsSteps-CBcAYOuP.js";import{C as u}from"./CsPullquote-COh6crXd.js";import{C as n}from"./CsCallout-C4nnLEHM.js";import{C as p}from"./CsCredits-DAUbZekd.js";import{C as m}from"./CsImage-ByVeeHce.js";import{C as g}from"./CsCompareTable-CPz5d1hR.js";import{C as f}from"./CsFlowDiagram-BgYkKlGd.js";import{C as y}from"./CsBeforeAfter-LcitIXGW.js";import{C as w}from"./CsThanks-Cx9c-DN_.js";import{B as b}from"./BottomNav-BQIsGLMm.js";import"./vendor-react-P2F7fkol.js";import"./vendor-three-CMud_36L.js";function B(){return e.jsxs(e.Fragment,{children:[e.jsxs(r,{children:[e.jsx("title",{children:"Clawed · Parth Pawar"}),e.jsx("meta",{name:"description",content:"Clawed.chat — Personal AI assistant for people on the go. Smart glasses integration, safety-first design, and receipts for every action. Case study by Parth Pawar, Product Designer."}),e.jsx("meta",{property:"og:type",content:"article"}),e.jsx("meta",{property:"og:title",content:"Clawed · Parth Pawar"}),e.jsx("meta",{property:"og:description",content:"Personal AI assistant for people on the go. Safety-first design with smart glasses integration and receipts for every action."}),e.jsx("meta",{property:"og:image",content:"https://parthpawar.com/Assets/images/clawed.png"})]}),e.jsx(o,{}),e.jsxs("main",{id:"main-content",className:"project-main",style:{"--project-color":"#8B5E34"},children:[e.jsx(d,{backLink:"/work",categorySlug:"ai",backLabel:"Back to Work",tags:["AI Assistant","Smart Glasses","Product Design","Full-stack Design"],title:"Clawed",subtitle:"Personal AI assistant for people on the go — smart glasses integration for glanceable, hands-free interactions plus a full web hub with safety modes, receipts, and one-tap approvals",info:[{label:"Role",value:"Product Designer (sole designer + 3 engineers)"},{label:"Timeline",value:"Jan – Mar 2026 (~10 weeks)"},{label:"Status",value:"Shipped to production, early user testing phase"},{label:"Platform",value:"Web + Smart Glasses (via Mentra integration)"}],liveUrl:"https://clawed.chat",heroImage:"/Assets/images/clawed.png",heroAlt:"Clawed.chat — Personal AI assistant with smart glasses integration"}),e.jsx(h,{id:"cs-vision",sections:[{label:"The Vision",content:"AI assistants promise to handle your life. In practice, they handle your patience. You ask them to do something, they hallucinate a confident answer, execute without asking, and leave no trail when things go wrong. Clawed exists to fix that. It is a personal AI assistant built around one conviction: if an AI acts on your behalf, you should be able to ask it under 3 seconds, get results in under 5, approve with one tap, and always have a receipt."},{label:"My Role",content:"As the sole Product Designer, I owned the entire design surface of Clawed: the marketing site, the web application with eight core pages, the smart glasses experience, the safety mode system, and the design language that holds it all together. I worked alongside an engineering team to ship a product built on React 19, TypeScript, and Tailwind — designing every screen, interaction, and approval flow from first pixel to production."}]}),e.jsxs(s,{id:"cs-context",label:"01 — Context",title:"Why AI Assistants Fail",children:[e.jsxs(t,{children:[e.jsx("p",{children:"Before I designed forward, I studied the failures. AI assistants have a trust problem, and it is entirely self-inflicted. Siri, Alexa, Google Assistant — each one trained users to expect disappointment. The pattern was always the same: promise the world, deliver a timer and a weather forecast, and quietly lose credibility every time the assistant guessed wrong and acted anyway."}),e.jsx("p",{children:"The deeper problem is not capability. It is accountability. When an AI sends an email on your behalf with the wrong tone, there is no undo. When it books a flight you did not actually confirm, there is no receipt. When it misinterprets a voice command while you are driving, there is no safety net. Every major assistant treats autonomy as a feature and accountability as someone else’s problem."}),e.jsx("p",{children:"The result is a generation of users who have learned to distrust the AI that is supposed to help them. They default to doing things manually — not because the AI cannot do it, but because they cannot trust that it will."})]}),e.jsx(n,{children:e.jsx("p",{children:"“The problem with AI assistants is not that they are too dumb. It is that they are too confident. An assistant that acts without asking and fails without apologizing is not an assistant — it is a liability.”"})}),e.jsx(y,{title:"The Trust Gap",before:{label:"Existing Assistants",items:["Acts autonomously without confirmation","No record of what was done or why","Errors are silent and irreversible","Same permission level for all contexts","Users learn to distrust and stop using"]},after:{label:"Clawed",items:["Always asks before acting on your behalf","Immutable receipt for every action taken","Staging area catches mistakes before they ship","Context-aware safety modes (driving vs. desk)","Trust builds gradually — users opt into more autonomy"]}})]}),e.jsxs(s,{id:"cs-research",label:"02 — Research",title:"What Users Actually Need from an AI Assistant",children:[e.jsx(t,{children:e.jsx("p",{children:"I audited seven AI assistants (Siri, Alexa, Google Assistant, Copilot, Rabbit R1, Humane Pin, ChatGPT) across three dimensions: what they promise, where they fail, and how users work around the failures. The pattern was consistent: users develop “trust ceilings” — a maximum level of autonomy they will grant an AI before reverting to manual work."})}),e.jsx(a,{features:[{title:"Trust Ceiling Pattern",desc:"Users start enthusiastic, hit one bad auto-action (wrong email tone, bad calendar invite), and permanently reduce their usage to only safe queries like weather and timers."},{title:"Accountability Gap",desc:`No existing assistant shows what it did, why, or lets you undo it. Users described feeling like they were "handing keys to someone who won't tell me where they drove."`},{title:"Context Blindness",desc:"Every assistant uses the same permission model whether you are at your desk or driving at 60 mph. No contextual safety adjustment exists in any product on the market."},{title:"Approval Fatigue vs. Trust",desc:"Users want to approve actions, but only if approval is fast. If confirming takes longer than doing it manually, they skip the assistant entirely."}]}),e.jsx(n,{children:e.jsxs("p",{children:["The core insight: users do not want a smarter AI. They want an AI they can verify. The design principle that emerged: ",e.jsx("strong",{children:"ask in 3 seconds, results in 5, approve in 1 tap, always leave a receipt."})]})})]}),e.jsxs(s,{id:"cs-challenges",label:"03 — Design Challenges",title:"Four Problems That Shaped Every Decision",children:[e.jsx(t,{children:e.jsx("p",{children:"Clawed is not one product. It is a web hub, a glasses experience, a command bar, an approval system, and a receipt ledger — all of which need to feel like the same product whether you are at your desk or walking down the street. Every design challenge came back to the same question: how do you make an AI assistant feel fast, safe, and coherent across fundamentally different contexts?"})}),e.jsx(a,{features:[{title:"Glanceable on Glasses",desc:"Smart glasses give you seconds, not minutes. Every piece of information the AI surfaces on the glasses display needs to be understood in a single glance — no scrolling, no reading paragraphs, no squinting at fine print. I designed a card-based system where every response fits into a structured template: icon, one-line summary, action button. If it does not fit the card, it gets pushed to the web hub."},{title:"Trust Through Transparency",desc:"Users do not trust AI by default. They trust AI that shows its work. Every action Clawed takes generates a receipt — a timestamped, human-readable record of what happened, what the AI recommended, what the user approved, and what the outcome was. The receipt system is not a logging feature. It is the core trust mechanism of the entire product."},{title:"Command-Line Speed + GUI Comfort",desc:"Power users want keyboard shortcuts and a command bar. New users want buttons and visual cues. Clawed’s Command Bar (⌘K) bridges both worlds — a fuzzy-search interface that lets you type natural language or structured commands, with inline previews and one-keystroke execution. Every action available in the GUI is available in the command bar, and vice versa."},{title:"Multi-Device Coherence",desc:"The same user might ask Clawed something on their glasses while walking, approve the result on their phone at a stoplight, and review the receipt on their laptop at the office. The design system needed to be device-aware without being device-dependent — the same information architecture, adapted to each context, with state that syncs seamlessly across all three."}]})]}),e.jsxs(s,{id:"cs-webhub",label:"04 — Web Hub",title:"The Brain You Come Back To",children:[e.jsxs(t,{children:[e.jsx("p",{children:"The glasses handle the moments. The web hub handles the thinking. It is where you manage your inbox, review AI-drafted responses, configure safety modes, browse your timeline of actions, and connect third-party services. I designed eight core pages — Dashboard, Inbox, Ask, Approvals, Timeline, Connections, Devices, and Settings — each built around the same principle: show the most important thing first, hide everything else behind progressive disclosure."}),e.jsx("p",{children:"The Dashboard is the home screen — a single-glance summary of pending approvals, recent actions, inbox count, and active safety mode. No widgets to configure, no drag-and-drop customization. The AI decides what is important based on context and recency. If you have three emails waiting for approval, that is the first thing you see. If your glasses are disconnected, that surfaces as an alert. The Dashboard is not a canvas — it is an opinionated briefing."})]}),e.jsx(m,{src:"/Assets/Projects/website-screenshot/screencapture-clawed-chat-2026-03-25-13_35_05.png",alt:"Clawed.chat full website — hero section with 3D lobster mascot, deployment steps, comparison table, smart glasses integration, community testimonials, and CTA"}),e.jsx("p",{className:"cs-caption",children:"The live clawed.chat marketing site — designed to communicate the safety-first AI philosophy with clear deployment steps, comparison tables, and smart glasses integration messaging"}),e.jsx("h3",{className:"cs-section-subtitle",children:"Inbox & Ask"}),e.jsxs(t,{children:[e.jsx("p",{children:"The Inbox is not an email client. It is a triage interface. Every incoming message is pre-analyzed by the AI, tagged with urgency and suggested action, and presented as a card with three options: approve the AI’s draft, edit before sending, or dismiss. You can clear your inbox without reading a single full email — the AI summaries are that good — but every action generates a receipt so you can audit later."}),e.jsx("p",{children:"Ask is the AI chat interface — the place where you have longer conversations, ask follow-up questions, and request complex multi-step actions. It is designed to feel like a messaging app, not a search engine. Responses are structured, actionable, and always end with a clear next step: approve, modify, or cancel. The command bar (&Cmd;K) is always one keystroke away, and every response can be pinned, shared, or turned into a recurring workflow."})]})]}),e.jsxs(s,{id:"cs-glasses",label:"05 — Glasses Experience",title:"Intelligence at the Edge of Your Vision",children:[e.jsx(t,{children:e.jsx("p",{children:"The glasses are not a second screen. They are a first responder. When you ask Clawed something while walking, cooking, or commuting, the glasses display is where the answer appears — instantly, glanceably, and with a single-tap approval path. I designed a glasses simulator that lets the team prototype and test every interaction without physical hardware, ensuring that every card, notification, and approval prompt works at peripheral-vision scale."})}),e.jsx("h3",{className:"cs-section-subtitle",children:"Card Types"}),e.jsx(t,{children:e.jsx("p",{children:"Every piece of information on the glasses display is a card. I designed four card types that cover 95% of use cases: Info cards (weather, calendar, quick facts), Action cards (approve, dismiss, snooze), Receipt cards (confirmation of completed actions), and Alert cards (safety warnings, disconnection notices). Each card follows a strict template — icon on the left, one line of text in the center, action on the right — so the user’s eye never has to hunt for what to do next."})}),e.jsx("h3",{className:"cs-section-subtitle",children:"Glanceable Design Principles"}),e.jsx(i,{steps:[{num:"1",title:"One Line Max",desc:"Every glasses response is one line of text. If the AI cannot summarize it in one line, it pushes the full response to the web hub and shows a “See details on web” card instead."},{num:"2",title:"3-Second Rule",desc:"Every card auto-dismisses after 3 seconds unless the user engages. No notification pile-up, no clutter. If you missed it, the web hub has the full history."},{num:"3",title:"One Action Per Card",desc:"No multi-button dialogs on a peripheral display. Every card has exactly one action: tap to approve, tap to dismiss, or tap to expand on web. Decision fatigue is the enemy of glanceable design."},{num:"4",title:"Always a Receipt",desc:"Every action taken on the glasses generates a receipt that syncs to the web hub. You can glance and approve with confidence because the paper trail is automatic."}]})]}),e.jsxs(s,{id:"cs-safety",label:"06 — Safety Architecture",title:"Three Tiers of Trust",children:[e.jsx(t,{children:e.jsx("p",{children:"Not every situation calls for the same level of AI autonomy. Driving requires a different safety posture than sitting at your desk. Clawed’s Safety Mode system gives users explicit control over how much the AI can do — not through buried settings, but through a prominent, always-visible toggle that changes the entire interaction model."})}),e.jsx(g,{title:"Safety Mode Comparison",columns:["Read Only","Draft First","Assisted"],rows:[{feature:"Read & summarize",values:[!0,!0,!0]},{feature:"Draft responses",values:[!1,!0,!0]},{feature:"Execute actions",values:[!1,!1,!0]},{feature:"Requires approval per action",values:["N/A","Always","Pre-approved types only"]},{feature:"Generates receipts",values:[!1,!0,!0]},{feature:"Best context",values:["Driving, meetings","Default — daily use","Trusted, repetitive tasks"]}]}),e.jsxs("details",{className:"cs-details",children:[e.jsx("summary",{className:"cs-details-summary",children:"Deep dive: How the safety architecture prevents accidental actions"}),e.jsxs("div",{className:"cs-details-content",children:[e.jsx("p",{children:"The safety architecture is built on three layers of protection that work together to eliminate accidental AI actions."}),e.jsxs("p",{children:[e.jsx("strong",{children:"Layer 1: Permission boundaries."})," Each safety mode defines a hard boundary for what the AI can do. In Read Only, the AI literally cannot access send or execute functions — the API calls are blocked at the permission layer, not just hidden in the UI. This is not a cosmetic change. It is a structural one."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Layer 2: The staging area."})," In Draft First mode, every AI-generated action lands in a staging area before it can touch the outside world. The staging area shows you exactly what the AI wants to do, who it will affect, and what the original request was. You can edit, approve, or discard. Nothing escapes without a deliberate tap."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Layer 3: The receipt ledger."})," Every action — whether manually approved or auto-executed in Assisted mode — generates an immutable receipt. Receipts include the original request, the AI’s recommendation, the user’s decision, the timestamp, and the outcome. The receipt ledger is searchable, filterable, and exportable. It is the audit trail that makes the entire system trustworthy."]}),e.jsx("p",{children:"During user testing, the most common feedback was not about the AI’s intelligence. It was about the feeling of control. Users described the safety modes as “a volume knob for AI trust” — something they could adjust based on context without ever worrying about the AI overstepping."})]})]}),e.jsx(f,{title:"Approval Workflow",nodes:[{label:"User Request",desc:"Voice or text input"},{label:"AI Processes",desc:"Analyzes intent, drafts response"},{label:"Staging Area",desc:"Draft held for review",accent:!0},{label:"One-Tap Approve",desc:"User confirms or edits"},{label:"Receipt Generated",desc:"Immutable record created"}]}),e.jsx(u,{quote:"It is like a volume knob for how much I trust the AI right now. Driving home? Turn it down to Read Only. At my desk with coffee? Crank it to Assisted. I have never felt that kind of control with any other assistant.",cite:"Stakeholder feedback during internal review"})]}),e.jsxs(s,{id:"cs-impact",label:"07 — Impact",title:"Early Signals & Honest Assessment",children:[e.jsx(t,{style:{marginBottom:"2rem"},children:e.jsx("p",{children:"Clawed shipped to production in Q1 2026 and is in early user testing. I want to be transparent: we do not have large-scale analytics yet. What follows are qualitative signals from 6 moderated testing sessions (45 minutes each, mix of technical and non-technical participants) and internal team observations from the 10-week build."})}),e.jsxs(t,{children:[e.jsx("h3",{className:"cs-section-subtitle",children:"Design principles as team alignment tools"}),e.jsx("p",{children:"The five principles — Safety First, Receipts for Everything, Glanceable, Progressive Disclosure, Keyboard Friendly — became the shared language between me and the engineering team. When a feature request violated “Glanceable,” we pointed at the principle instead of debating for a week. When an engineer asked whether a new action type needed a receipt, the answer was always yes. This saved roughly two to three scope debates per week — a process improvement, not a user-facing metric."})]}),e.jsxs(t,{style:{marginTop:"1.5rem"},children:[e.jsx("h3",{className:"cs-section-subtitle",children:"User testing observations (n=6)"}),e.jsx("p",{children:"In moderated sessions, 5 of 6 participants started in Read Only mode and voluntarily upgraded to Draft First within 10–15 minutes. 2 of 6 reached Assisted mode by session end. The graduated trust model worked as designed — users opted into more autonomy because the guardrails gave them confidence."}),e.jsx("p",{children:"An unexpected finding: 4 of 6 participants used the receipt timeline as a personal productivity log, reviewing what they had accomplished at the end of the session. The accountability feature doubled as a reflection tool — something I had not designed for."})]}),e.jsxs("details",{className:"cs-details",children:[e.jsx("summary",{className:"cs-details-summary",children:"What I would measure at scale"}),e.jsxs("div",{className:"cs-details-content",children:[e.jsx("p",{children:"If Clawed scaled to thousands of users, the metrics I would track are the ones that matter for a trust-first product — not engagement vanity metrics, but trust indicators."}),e.jsxs("p",{children:[e.jsx("strong",{children:"Safety mode graduation rate:"})," How quickly do new users move from Read Only to Draft First to Assisted? A healthy product sees steady, voluntary progression. A stalled product means users do not trust the AI enough to give it more autonomy."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Revert rate:"})," How often do users undo or override an AI-executed action? A declining revert rate means the AI is learning user preferences. A flat or rising one means the approval flow is doing its job but the AI is not improving."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Receipt review frequency:"})," How often do users actually look at their receipts? Early testing suggested receipts served a dual purpose (audit + reflection), and tracking this would reveal whether the trust mechanism is also a retention mechanism."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Time-to-approval:"})," How long does a user spend reviewing an AI draft before approving it? Decreasing time-to-approval signals growing trust. Increasing time signals the AI is drafting things the user does not agree with."]})]})]})]}),e.jsx(s,{id:"cs-learnings",label:"08 — Key Learnings",title:"What Designing a Safety-First AI Taught Me",children:e.jsx(a,{features:[{title:"Constraints compress quality",desc:'The "3 seconds to ask, 5 seconds to results, 1 tap to approve" constraint forced every interaction to be lean and decisive. Without it, Clawed would have become another general-purpose chat. With it, every screen had a job.'},{title:"Trust is a design material",desc:"Receipts, safety modes, and approval workflows are not features bolted on. They are the product. Trust is not the absence of risk — it is the presence of transparency. Users need an AI that shows its work."},{title:"Multi-device ≠ responsive",desc:"Resizing layouts for different screens is solved. Making the same information architecture work across glasses, phone, and desktop — each with fundamentally different interaction models — requires rethinking, not resizing."},{title:"Principles > components",desc:'The five design principles saved more time than any design system component. When a feature violated "Glanceable," we pointed at the principle and moved on. Good principles are operational, not aspirational.'}]})}),e.jsxs(s,{id:"cs-whats-next",label:"09 — What’s Next",title:"Where Clawed Goes From Here",children:[e.jsx(t,{children:e.jsx("p",{children:"Clawed shipped as a fully functional product, but it is the foundation — not the ceiling. The next phase focuses on three areas informed by early user testing signals."})}),e.jsx(i,{steps:[{num:"1",title:"Workflow Automation",desc:'Let users chain multiple actions into repeatable workflows: "Every Monday, summarize my unread emails, draft replies to urgent ones, and archive newsletters." The receipt system already supports multi-step audit trails.'},{num:"2",title:"Team Mode",desc:"Extend safety modes to shared accounts. A team lead could set permission boundaries for the whole team — e.g., junior members use Draft First, senior members use Assisted — with receipts rolling up to a team dashboard."},{num:"3",title:"Context-Aware Auto-Switching",desc:'Use location + calendar signals to automatically adjust safety modes. When your calendar says "Driving," the system switches to Read Only. When you arrive at the office, it reverts to your default. No manual toggle needed.'}]})]}),e.jsx(s,{label:"Credits",title:"Team",children:e.jsx(p,{credits:[{role:"Product Designer",name:"Parth Pawar"},{role:"Product",name:"Clawed.chat"},{role:"Tools",name:"Figma, React 19, TypeScript, Tailwind CSS 4"},{role:"Platforms",name:"Web, Smart Glasses"}]})}),e.jsx(w,{contactCta:!0}),e.jsx(b,{sections:[{id:"cs-vision",label:"Vision & Role"},{id:"cs-context",label:"Context"},{id:"cs-research",label:"Research"},{id:"cs-challenges",label:"Challenges"},{id:"cs-webhub",label:"Web Hub & Site"},{id:"cs-glasses",label:"Glasses"},{id:"cs-safety",label:"Safety"},{id:"cs-impact",label:"Impact"},{id:"cs-learnings",label:"Learnings"},{id:"cs-whats-next",label:"What’s Next"}],liveUrl:"https://clawed.chat"})]}),e.jsx(c,{slug:"oncall-lens",title:"OnCall Lens",image:"/Assets/images/oncall-lens.png"}),e.jsx(l,{})]})}export{B as default};
